#pragma once#include "MyTreeCtrl.h"// CTreeListView viewclass CTreeListView : public CView{  //************************************ struct _HeaderData *************************************************  //@struct Structure for nessassary data wich is to be got from the header for drawing  struct _HeaderData  {	  long nWidth;		//@field width of the column	  RECT rcDefault;		//@field Rectangle of the ColumnHeaderItem (used for left and right value of the item's column)	  UINT nAlingment;	//@field alignment of the column  };  typedef struct _HeaderData HeaderData;  //************************************ CMyTreeObj *********************************************************  // @class A class that holds the texts of the columns for each item.  // I use this class, so I can use a CMap to get the columntexts to a HTREEITEM, because  // CMap wants to have Objects in it that have got an operator=.  // @base public | CObject  class CMyTreeObj : public CObject  {  // public mebers  public:	  // @cmember dynamic array that holds the columntextes for one object	  CStringArray m_strColumns;	  // @cmember operator= to copy the StringArray from one object to an other	  CMyTreeObj& operator=(CMyTreeObj& obj);  };	DECLARE_DYNCREATE(CTreeListView)protected:	CTreeListView();           // protected constructor used by dynamic creation	virtual ~CTreeListView();public:	virtual void OnDraw(CDC* pDC);      // overridden to draw this view  virtual BOOL OnNotify(WPARAM wParam, LPARAM lParam, LRESULT* pResult);#ifdef _DEBUG	virtual void AssertValid() const;#endifprotected:  CMyTreeCtrl   m_ctrlTree;  // @cmember contained headercontrol  CHeaderCtrl		m_ctrlHeader;  // @cmember List of columntextes, which can be reached with the corresponding treeitem handle  CMap<HTREEITEM, HTREEITEM, CMyTreeObj, CMyTreeObj&> m_Entries;  // @cmember structure with data of the columns. used that we needn't get that values all times at drawing  HeaderData*		m_vsCol;  // @cmember backgroundcolor, not really used but inserted for drawing (set to default)  COLORREF		m_colBackColor;  // @cmember color of the text of a selected element  COLORREF		m_colHilightText;  // @cmember textcolor, not really used but inserted for drawing (set to default)  COLORREF		m_colText;  // @cmember brush to fill the background of a selected element  CBrush			m_BackBrush;  // a proposal from codeguru (anonymus)  CBrush			m_BackBrushNormal;  // @cmember should the header be displayed?  bool			m_bDescriptionDisplay;  // @cmember Scrollingposition of the view  long			m_nOffset;  // @cmember width of the header, safed for scrolling  long			m_nHeaderWidth;  // @cmember -number of columns used  long			m_nNrColumns;protected:  // @cmember calculates the rectangles for the childcontrols  void CalculateClientRects(CRect& rcBase, CRect& rcTree, CRect& rcHeader);  // @cmember resizes all childobjects of the view  void SizeObjects(void);  // @cmember checks, if the horizontal scrollbar is necessary and,hides / shows it  bool ResetScrollbar(void);  // @cmember draws the text of the treeitems (all columns!!)  void DrawTreeItem(bool bFocus, CRect rcItem, HDC hdc, HTREEITEM hItem);  // @cmember updates the m_vsCol variable to the actual value  void UpdateColStruct(void);  // @cmember set's up the drawingcontext and triggers the itemds textdrawing  BOOL OnCustomdrawTree(LPNMHDR pNmhdr, LRESULT* pResult);  // @cmember triggers the update of the m_vsCol - variable (user resized the Columns)  BOOL OnEndTrack(LPNMHDR pNmhdr, LRESULT* pResult);  // @cmember deletes all columndata for this object  BOOL OnDeleteItem(LPNMHDR pNmhdr, LRESULT* pResult);public:  // @group public Operations, used from the client  // @cmember Inserts a new column in the TreeListView  int InsertColumn( int nCol, const LVCOLUMN* pColumn );  // @cmember Inserts a new column in the TreeListView  int InsertColumn( int nCol, LPCTSTR lpszColumnHeading, int nFormat = LVCFMT_LEFT, int nWidth = -1, int nSubItem = -1 );  // @cmember Call this function to delete a column from the TreeListView control  BOOL DeleteColumn( int nCol );  // @cmember Changes the text of a list view subitem  BOOL SetSubItemText( HTREEITEM hItem, int nSubItem, CString strBuffer);  // @cmember Retrieves the text of a list view subitem  BOOL GetSubItemText( HTREEITEM hItem, int nSubItem, CString& strBuffer);  // @cmember Retrieves the handle of the Header control used  CImageList* GetHeaderImageList();  // @cmember Assigns an image list to the Header control  CImageList* SetHeaderImageList( CImageList * pImageList);  // @cmember Returns a reference to the tree control associated with the view  CTreeCtrl& GetTreeCtrl();  // @cmember Shows or hides the Header control  void ShowHeader(bool bShow);  int OnCreateK(LPCREATESTRUCT lpCreateStruct, DWORD exStyle = 0);	DECLARE_MESSAGE_MAP()  // @cmember creates the childcontrols  afx_msg int OnCreate(LPCREATESTRUCT lpCreateStruct);  // @cmember resizes the childcontrols  afx_msg void OnSize(UINT nType, int cx, int cy);  // @cmember scrolls the tree and the header  afx_msg void OnHScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);  afx_msg LRESULT OnInsertItem(WPARAM wParam, LPARAM lParam);};